{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How many days can you spend in Arizona before being presumed a resident?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Up to nine months in the aggregate during the tax year. Past more than nine months, roughly 270 days, Arizona presumes you are a resident, though the presumption can be rebutted."
      }
    },
    {
      "@type": "Question",
      "name": "Can the Arizona nine-month presumption be rebutted?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. It may be overcome by competent evidence that you are in Arizona for a temporary or transitory purpose. The day count shifts the burden to you but does not make residency final."
      }
    },
    {
      "@type": "Question",
      "name": "How is time in Arizona counted for this rule?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "In the aggregate across the whole taxable year, so periods do not need to be consecutive. Roughly 270 days, or more than nine months, is the point at which the presumption arises."
      }
    }
  ]
}

