{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How many days can you stay in Australia without becoming a tax resident?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Fewer than 183 days in an income year keeps you outside the 183-day test. At 183 days or more you are presumed a resident, unless your usual place of abode is outside Australia and you do not intend to take up residence here."
      }
    },
    {
      "@type": "Question",
      "name": "Is the 183-day test based on the calendar year?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "No. Days are totalled across the income year, 1 July to 30 June, they do not need to be consecutive, and the count resets each new income year."
      }
    },
    {
      "@type": "Question",
      "name": "Does 183 days automatically make you an Australian tax resident?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Not automatically. It is one of several ATO tests, and reaching 183 days creates a presumption of residence that is rebutted if your usual place of abode is outside Australia and you do not intend to settle here."
      }
    }
  ]
}

