{
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
      {
        "@type": "Question",
        "name": "How many days can you stay in Bulgaria without becoming a tax resident?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Up to 183 days in any 12-month window. Reach 184 or more in any window and the day-count test is met. Remember that both your arrival day and departure day count."
        }
      },
      {
        "@type": "Question",
        "name": "Is Bulgaria's rule based on the calendar year?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "No. It uses any rolling 12-month period. Once you cross 183 days, though, you are treated as resident for the calendar year in which you crossed the line."
        }
      },
      {
        "@type": "Question",
        "name": "Do education or medical stays count?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "No. Days spent in Bulgaria solely for education or medical treatment are excluded from the 183-day total."
        }
      }
    ]
  }

