{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How many days can you spend in California without becoming a resident?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "There is no fixed line. Residency is a closest-connections test, not a day count. But more than nine months in the state, roughly 270 days, creates a rebuttable presumption of residency. Fewer than nine months does not presume you are a nonresident."
      }
    },
    {
      "@type": "Question",
      "name": "Does the nine-month presumption make you a resident automatically?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "No. It is rebuttable. You can overcome it by showing the stay was for a temporary or transitory purpose, though the burden is on you. You can also be a resident with little time in the state if your closest connections are there."
      }
    },
    {
      "@type": "Question",
      "name": "What is a temporary or transitory purpose?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "A stay that is not a settled, permanent connection to California, such as a vacation, a short assignment, or passing through. Being present for such a purpose points toward nonresidency, even while you are physically in the state."
      }
    }
  ]
}

