{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How many days can you stay in Canada without becoming a tax resident?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Fewer than 183 days in a calendar year keeps you below the sojourner threshold. Reach 183 days or more and you are a deemed resident for the entire year. Days need not be consecutive and any part of a day counts. Residential ties can make you resident with fewer days."
      }
    },
    {
      "@type": "Question",
      "name": "What is the difference between a deemed resident and a factual resident?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "A deemed resident sojourns 183 days or more in a calendar year without significant residential ties. A factual resident has established ties such as a home, spouse, or dependants in Canada and can be resident with far fewer days. Both are taxed on worldwide income."
      }
    },
    {
      "@type": "Question",
      "name": "Is the 183-day rule based on the calendar year?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. Days are totalled from 1 January to 31 December, they do not need to be consecutive, and the count resets each new year."
      }
    }
  ]
}

