{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How long can you stay in Canada as a visitor?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Most visitors may stay up to 6 months per entry. The border services officer can grant a shorter or longer period; a stamped or written date in your passport replaces the 6-month default."
      }
    },
    {
      "@type": "Question",
      "name": "What if your passport was not stamped on entry?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Your authorized stay ends 6 months after the day you entered Canada, or on your passport's expiry date, whichever comes first."
      }
    },
    {
      "@type": "Question",
      "name": "How do you stay in Canada longer than 6 months?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Apply online for a visitor record before your current status expires. Applying in time preserves your legal status while the application is processed."
      }
    }
  ]
}

