  "mainEntity": [
    {
      "@type": "Question",
      "name": "How many days can you stay in Colombia without becoming a tax resident?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Up to 183 calendar days in any 365-day period. Cross more than 183 in any window and you meet the residency test."
      }
    },
    {
      "@type": "Question",
      "name": "Is the 183-day rule based on the calendar year?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "No. It uses any period of 365 consecutive calendar days, so a stay split across two years can still cross the line, with residency applying from the second year."
      }
    },
    {
      "@type": "Question",
      "name": "Do the 183 days have to be consecutive?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "No. Continuous or discontinuous days both count, so several shorter trips inside the same 365-day window are added together."
      }
    }
  ]
}

