  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How many days can you spend in Colorado without becoming a statutory resident?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Up to six months (183 days) in the tax year. Beyond that, combined with a permanent place of abode, you become a statutory resident even if domiciled elsewhere."
      }
    },
    {
      "@type": "Question",
      "name": "What counts as time spent in Colorado?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Colorado measures time in the state in aggregate across the tax year. Separate trips add up, and the days do not need to be consecutive."
      }
    },
    {
      "@type": "Question",
      "name": "Do you need a home in Colorado to be caught by the rule?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "For the statutory test, yes. A permanent place of abode can be a house, condominium, apartment, room, or mobile home, and you need not own or lease it yourself. Without one there is no statutory residence on days alone, though separate domicile rules can still make you a resident."
      }
    }
  ]
}

