{
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
      {
        "@type": "Question",
        "name": "How many days can you stay in Cyprus without becoming a tax resident?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Up to 183 days in a calendar year. Because the arrival day counts in and the departure day counts out, that is really 183 nights, so 184 or more triggers residency under the main test."
        }
      },
      {
        "@type": "Question",
        "name": "What is the Cyprus 60-day rule?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "An alternative test: you are resident on as few as 60 days if, in the same year, you stay at least 60 days in Cyprus, spend no more than 183 days in any other single country, have a business, job or office in a Cyprus company, and keep a permanent home in Cyprus that you own or rent. All four conditions must hold. A fifth condition, not being tax resident elsewhere, was removed from 1 January 2026."
        }
      },
      {
        "@type": "Question",
        "name": "Is the Cyprus rule based on the calendar year?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes. The Cyprus tax year is the calendar year, and both the 183-day rule and the 60-day rule are measured over it rather than a rolling 12-month window."
        }
      }
    ]
  }

