    {
      "@type": "Question",
      "name": "How many days can you stay in Georgia (the country) without becoming a tax resident?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Fewer than 183 days in any continuous 12-month period ending in the tax year. Reach 183 and the day-count test is met for that year."
      }
    },
    {
      "@type": "Question",
      "name": "Is the 183-day rule based on the calendar year?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Georgia's tax year is the calendar year, but the 183 days are counted across any continuous 12-month window ending in that year, so a stay split across two years can still cross the line."
      }
    },
    {
      "@type": "Question",
      "name": "Do all days in Georgia count?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Most do. The Tax Code excludes days spent purely in transit, days only for treatment or rest, and days held with diplomatic or consular status."
      }
    }
  ]
}

