{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How many days can you spend in Georgia without becoming a resident?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Fewer than 183 across any 12 consecutive months. Once you have resided in Georgia for 183 days or more in the aggregate over the immediately preceding 365 days, the day-count test makes you a resident individual."
      }
    },
    {
      "@type": "Question",
      "name": "Is Georgia's rule based on a calendar year?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "No. It looks back over the immediately preceding 365 days to income tax day, so the window is any 12 consecutive months rather than a fixed 1 January to 31 December year. It does not reset each January."
      }
    },
    {
      "@type": "Question",
      "name": "Do you need a home in Georgia to be caught by the rule?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "No. Unlike states that require a permanent place of abode, Georgia's 183-day test turns on physical presence alone."
      }
    }
  ]
}

