  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How long can you stay in Georgia visa-free?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Citizens of the countries on Georgia's visa-free list may enter and stay for one full year per entry, counted from the day of arrival. A few listed countries carry shorter terms."
      }
    },
    {
      "@type": "Question",
      "name": "Does leaving Georgia reset the visa-free year?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "In practice yes: the year is a continuous per-entry allowance, so a new entry starts a new stay. Admission is still decided at the border each time, so a long-running border-run pattern is not a guarantee."
      }
    },
    {
      "@type": "Question",
      "name": "Is this the same as Georgian tax residency?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "No. Immigration and tax are separate: spending 183 or more days in Georgia during any 12-month period can make you a tax resident even though your immigration status is a simple visa-free stay."
      }
    }
  ]
}

