  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How many days can you spend in Hawaii before you are presumed a resident?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Up to 200 days in the taxable year. More than 200 days, counted in the aggregate, creates a rebuttable presumption that you were a Hawaii resident from the time of your arrival."
      }
    },
    {
      "@type": "Question",
      "name": "Can you rebut Hawaii's 200-day presumption?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. The presumption is rebuttable with evidence satisfactory to the Department of Taxation that you maintain a permanent place of abode outside Hawaii and were in the state only for a temporary or transitory purpose."
      }
    },
    {
      "@type": "Question",
      "name": "Do the 200 days have to be consecutive?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "No. The days are counted in the aggregate across the taxable year and do not need to be consecutive."
      }
    }
  ]
}

