  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How many days can you spend in Idaho without becoming a resident?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Up to 270 days in the tax year. If you also keep a home in Idaho for the whole year, spending more than 270 days (271 or more) makes you a resident, even if you are domiciled elsewhere. Exactly 270 days keeps you under the day test."
      }
    },
    {
      "@type": "Question",
      "name": "What counts as a day in Idaho?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Presence in Idaho for any part of a calendar day counts as a full day, unless you can show the presence was for a temporary or transitory purpose."
      }
    },
    {
      "@type": "Question",
      "name": "Do you need a home in Idaho to be caught by the rule?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "For the 270-day test, yes. Without a place of abode kept for the tax year there is no day-count residency, though separate domicile rules can still make you an Idaho resident."
      }
    }
  ]
}

