  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How many days can you stay in Ireland without becoming a tax resident?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Up to 182 days in a single tax year keeps you below the main threshold; 183 or more makes you resident. Watch the second test too: 280 days or more across the current and previous year combined also makes you resident."
      }
    },
    {
      "@type": "Question",
      "name": "What is Ireland's 280-day rule?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Even if you are under 183 days in a single year, you are resident for a year if your days present total 280 or more when that year is added to the year before. A year of 30 days or fewer is not counted toward the 280."
      }
    },
    {
      "@type": "Question",
      "name": "How does Ireland count a day of presence?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "You are present for a day if you are in Ireland for any part of it. The tax year is the calendar year, so days are totalled from 1 January to 31 December and do not need to be consecutive."
      }
    }
  ]
}

