        "@type": "Question",
        "name": "Does Italy count the calendar year?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes. Residency is measured over the calendar year, 1 January to 31 December, and you are resident if a test is met for the greater part of it."
        }
      },
      {
        "@type": "Question",
        "name": "What changed in 2024?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "A physical-presence test was added that counts fractions of a day, so arrival and departure days both count, and anagrafe registration became a rebuttable presumption."
        }
      }
    ]
