  "mainEntity": [
    {
      "@type": "Question",
      "name": "How long can you stay in Japan without a visa?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Most of the 74 visa-exempt nationalities can stay up to 90 days per entry as a Temporary Visitor. Indonesia and Thailand get 15 days, Brunei and Qatar 30. The period on your landing permission is what counts."
      }
    },
    {
      "@type": "Question",
      "name": "Does Japan have a 90/180 rule like Schengen?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "No. Japan's limit is per entry, and no rolling window or annual cap is published. Immigration officers can still refuse entry when repeated visits look like de facto residence."
      }
    },
    {
      "@type": "Question",
      "name": "Does leaving Japan reset the 90 days?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Each new entry brings a fresh landing examination and a fresh period of stay, but there is no published formula and no guaranteed reset. Frequent long stays with short gaps can lead to refusal at the border."
      }
    }
  ]
}

