      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Up to 183 days in a calendar year. If you are present for more than 183 days in one year, you are treated as a Maltese tax resident for that year, whatever the purpose of your stay."
      }
    },
    {
      "@type": "Question",
      "name": "Is the 183-day rule based on the calendar year?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. Days are totalled from 1 January to 31 December, they do not need to be consecutive, and the count resets each new year."
      }
    },
    {
      "@type": "Question",
      "name": "Does becoming a Maltese tax resident mean my worldwide income is taxed?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Not automatically. Residency lets Malta tax you; domicile sets the scope. Residents domiciled in Malta are taxed on worldwide income, while non-domiciled residents are generally taxed only on Maltese income and foreign income remitted to Malta."
      }
    }
  ]
