      "name": "How many days can you stay in Mauritius without becoming a tax resident?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Fewer than 183 days in a single income year, and you must also stay under the 270-day aggregate test. Reaching 183 or more in one income year, or 270 or more across the current income year and the two before it, makes you a resident."
      }
    },
    {
      "@type": "Question",
      "name": "What is the income year for Mauritius tax residency?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "It runs from 1 July to 30 June, not the calendar year. Days are added up across that window for the 183-day test, and across three such windows for the 270-day test."
      }
    },
    {
      "@type": "Question",
      "name": "What is the 270-day rule in Mauritius?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "A second residence test: if your days total 270 or more across the current income year and the two preceding ones, you are resident even if no single year reached 183 days."
      }
    }
  ]
}

