  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How many contact periods can you have in Ohio without being a presumed resident?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Up to 212 in the calendar year. At 213 or more contact periods you are presumed to be an Ohio resident. Staying a presumed nonresident also requires an abode outside Ohio for the whole year and a filed Ohio Nonresident Statement (form IT 10)."
      }
    },
    {
      "@type": "Question",
      "name": "What is a contact period, and how is it different from a day?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "A contact period is essentially an overnight away from home: you are away overnight from your home outside Ohio and present for part of each of two consecutive days in the state. The night itself does not have to be spent in Ohio. A day trip where you sleep at your own home does not create a contact period, which is unlike an any-part-of-a-day count."
      }
    },
    {
      "@type": "Question",
      "name": "Do you have to file anything to be treated as an Ohio nonresident?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. Even with 212 or fewer contact periods and a home outside Ohio, the nonresident presumption depends on filing the Ohio Nonresident Statement (form IT 10, or the checkbox on the IT 1040) on time. Miss it and Ohio can presume you were domiciled in the state for the entire year."
      }
    }
  ]
}

