{
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
      {
        "@type": "Question",
        "name": "How many days can you stay in Poland without becoming a tax resident?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Up to 183 days in a calendar year. Exactly 183 does not trigger it, but 184 days or more in a single calendar year meets the day-count test."
        }
      },
      {
        "@type": "Question",
        "name": "Is Poland's rule rolling or calendar year?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Calendar year. Poland counts the 183 days within a single tax year (1 January to 31 December) and assesses each year on its own."
        }
      },
      {
        "@type": "Question",
        "name": "Can you be a Polish tax resident under 184 days?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes, through the centre-of-vital-interests test if your main personal or economic ties are in Poland. Either test alone is enough."
        }
      }
    ]
  }

