{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How many days can you spend in Rhode Island without becoming a statutory resident?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Up to 183 days in the calendar year. At 184 or more days, combined with a permanent place of abode kept in the state, you become a resident."
      }
    },
    {
      "@type": "Question",
      "name": "What counts as a day in Rhode Island?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Any part of a day spent in Rhode Island counts as a full day, except a part of a day spent solely while in transit to a destination outside the state."
      }
    },
    {
      "@type": "Question",
      "name": "Do you need a home in Rhode Island to be caught by the rule?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "For the statutory test, yes. Without a permanent place of abode there is no statutory residence on days alone, though separate domicile rules can still make you a resident."
      }
    }
  ]
}

