{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "Does the rule reset after 90 days out?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Not automatically in one block. Days become available as older Schengen stay days move outside the current 180-day lookback, so depending on your travel pattern they may come back gradually."
      }
    },
    {
      "@type": "Question",
      "name": "Is it 90 days per country?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "No. The 90 days cover the whole Schengen area combined. France, Spain, Italy, and the other members do not each give you a separate allowance."
      }
    },
    {
      "@type": "Question",
      "name": "Do arrival and departure days count?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. The day of entry is the first day of stay and the day of exit is the last, so even a late-night arrival puts that calendar date in the count."
      }
    }
  ]
}

