{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "What does a single-entry Schengen visa mean?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "It lets you enter the Schengen area once. The moment you leave, the visa is used up, even if authorized days remain and the validity dates have not expired. Returning requires a new visa."
      }
    },
    {
      "@type": "Question",
      "name": "What is the difference between number of entries and duration of stay?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "The number of entries (1, 2, or MULT) is how many times you may cross in. The duration of stay is the maximum days you may remain, printed in days. They are separate fields on the visa."
      }
    },
    {
      "@type": "Question",
      "name": "Does a single-entry visa still fall under the 90/180 rule?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. The printed duration of stay is a maximum, and it operates inside the general limit of 90 days in any 180-day period. A visa never authorizes more than the days it prints, nor more than that allowance permits."
      }
    }
  ]
}

