      },
      {
        "@type": "Question",
        "name": "Do transit days count?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "No. Time spent purely in transit through Serbia does not count, though for any other day being present for any part of it counts as a full day."
        }
      }
