{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How many days can you stay in Singapore without becoming a tax resident?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Fewer than 183 days in a calendar year. If your days of presence or employment reach 183 or more in one year, you are a Singapore tax resident for that year of assessment."
      }
    },
    {
      "@type": "Question",
      "name": "Is the 183-day rule based on the calendar year?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. Days are totalled from 1 January to 31 December in the year preceding the year of assessment, they do not need to be consecutive, and the count resets each new year."
      }
    },
    {
      "@type": "Question",
      "name": "Can you be a Singapore tax resident with fewer than 183 days in a year?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes, under IRAS concessions. Working across two straddling years with at least 183 days in total, or working continuously across three straddling years, can make you resident even where a single year falls short."
      }
    }
  ]
}

