{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How many days can you stay in Thailand without becoming a tax resident?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Up to 179 days in a calendar year. Under Section 41 of the Revenue Code, days aggregating 180 or more in one year make you a Thai tax resident for that year."
      }
    },
    {
      "@type": "Question",
      "name": "Is the 180-day rule based on the calendar year?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. Days are totalled from 1 January to 31 December, they do not need to be consecutive, and the count resets each new year."
      }
    },
    {
      "@type": "Question",
      "name": "Does becoming a Thai tax resident affect foreign income?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. Residents are taxed on Thai-source income and, from 2024, on foreign income brought into Thailand. Non-residents are generally taxed only on Thai-source income."
      }
    }
  ]
}

