  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How many days can you stay in Turkiye on a visa or visa exemption?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "At most 90 days within any 180-day period. The days need not be consecutive, and the 180-day window is rolling rather than a fixed calendar block."
      }
    },
    {
      "@type": "Question",
      "name": "Is the 90/180 rule a rolling window or a fixed period?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Rolling. On any given day you look back over the previous 180 days and add up your days in Turkiye; the total must not exceed 90. It is not a 90-in, 90-out reset."
      }
    },
    {
      "@type": "Question",
      "name": "How do you stay in Turkiye longer than 90 days?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Apply for a Short Term Residence Permit at the Provincial Directorate of Migration Administration. A visa or visa exemption cannot be extended past 90 days in 180."
      }
    }
  ]
}

