  "headline": "The UK Standard Visitor \"180-Day Rule\"",
  "description": "UK Standard Visitor rules allow up to 6 months per visit. There is no published 180-days-per-year formula; officers assess your pattern of visits instead.",
  "author": {
    "@type": "Organization",
    "name": "AtlasDays"
  },
  "publisher": {
    "@type": "Organization",
    "name": "AtlasDays"
  },
  "url": "https://atlasdays.app/learn/uk-standard-visitor-visa-180-day-rule",
  "datePublished": "2026-03-16",
  "dateModified": "2026-08-14"
}

{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "Is there a 180-days-per-year rule for UK visitors?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "No. The published rule is up to 6 months per visit; no \"6 months in any 12\" formula appears in the Immigration Rules. A pattern of visits that adds up to living in the UK can still lead to refusal."
      }
    },
    {
      "@type": "Question",
      "name": "Does leaving the UK reset your 6 months?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Each new visit carries its own allowance of up to 6 months, but re-entry is a fresh assessment: officers weigh your visits over the previous 12 months, the gaps between them, and whether you spend more time in the UK than at home."
      }
    },
    {
      "@type": "Question",
      "name": "Does an ETA let you stay longer in the UK?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "No. The Electronic Travel Authorisation is permission to travel to the UK, not a stay allowance. Visitors with an ETA are still subject to the Standard Visitor rules, including the up-to-6-months limit and the genuine-visitor test."
      }
    }
  ]
}

