{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "Is the UK a simple 183-day rule?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "No. 183 days or more in a tax year makes you resident automatically, but you can also become resident well below 183 days through a UK home, full-time UK work, or enough UK ties under the sufficient ties test."
      }
    },
    {
      "@type": "Question",
      "name": "How are UK days counted?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Generally by where you are at midnight: a day counts if you are in the UK at the end of it. Deeming and exceptional-circumstances rules can adjust the total, and the year is the UK tax year, 6 April to 5 April."
      }
    },
    {
      "@type": "Question",
      "name": "What is the FIG regime?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "From 6 April 2025 the remittance basis was replaced by the Foreign Income and Gains regime: new UK residents who were non-resident for the previous 10 tax years can shelter foreign income and gains for their first four years of residence."
      }
    }
  ]
}

