{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How long can you stay in the US on a B1/B2 visa?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "CBP decides at each arrival; B-1/B-2 visitors are typically admitted for up to 6 months per entry. The admitted-until date on your I-94 record is what controls, and it can be shorter."
      }
    },
    {
      "@type": "Question",
      "name": "Does the visa expiration date limit your stay?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "No. The visa expiration date is only the last day you may use the visa to seek entry at a port of entry. How long you may remain is set by the I-94 admitted-until date granted at admission."
      }
    },
    {
      "@type": "Question",
      "name": "How do you stay in the US longer than 6 months?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "File an extension-of-stay application with USCIS before your I-94 admitted-until date passes. Leaving and re-entering is not a guaranteed reset, since each entry is a new admission decision."
      }
    }
  ]
}

