{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How many days can you spend in Vermont without becoming a statutory resident?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Up to 183 days in the taxable year. At more than 183 days (184 or more), combined with a permanent place of abode, you become a statutory resident."
      }
    },
    {
      "@type": "Question",
      "name": "What counts as a day in Vermont?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Any part of a day spent in Vermont counts as a full day, with narrow exceptions. You do not need to sleep at the permanent place of abode for the day to count."
      }
    },
    {
      "@type": "Question",
      "name": "Do you need a home in Vermont to be caught by the rule?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "For the statutory test, yes. Without a permanent place of abode there is no statutory residence on days alone, though a separate domicile test can still make you a resident."
      }
    }
  ]
}

