{
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
      {
        "@type": "Question",
        "name": "How many days can you stay in Vietnam without becoming a tax resident?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Up to 182 days in a calendar year or in any 12 consecutive months. Reach 183 days or more in either window and the day-count test is met."
        }
      },
      {
        "@type": "Question",
        "name": "Does Vietnam use the calendar year or a rolling window?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Either one. You are resident if you reach 183 days in a calendar year, or 183 days in the 12 consecutive months counted from your first arrival."
        }
      },
      {
        "@type": "Question",
        "name": "Does renting a home make you resident?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "It can. A lease of 183 days or more can make you resident regardless of the day count, unless you prove tax residency in another country."
        }
      }
    ]
  }

