{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How many days can you spend in Virginia without becoming an actual resident?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Up to 183 days in the taxable year. At an aggregate of 184 or more days present or with a place of abode in Virginia, you become an actual resident even if domiciled elsewhere."
      }
    },
    {
      "@type": "Question",
      "name": "What counts as a day in Virginia?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Any portion of a day in which you are physically present counts as a full day, except for part of a day spent solely while in transit to a destination outside Virginia."
      }
    },
    {
      "@type": "Question",
      "name": "Does Virginia tax you if you are domiciled in another state?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. If you cross the 183-day line as an actual resident, Virginia taxes you even though your true, permanent home is in another state or country."
      }
    }
  ]
}

